using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Threading.Tasks;using UnityEngine;using UnityEngine.Rendering.Universal;using UnityEngine.InputSystem;using UnityEngine.InputSystem.LowLevel;using Demo6.Game;using Demo6.Core.Combat;
public static class UsabilityV5LightProbe{
 public static async Task<object> Run(string label="before"){if(!DungeonRoot.Instance||!UnityEditor.EditorApplication.isPlaying)throw new Exception("Dungeon Play required");var p=PlayerController.Instance;var cam=Camera.main;var follow=cam.GetComponent<DungeonCamera>();var original=p.Position;var oldKb=Keyboard.current;var oldMouse=Mouse.current;var kb=InputSystem.AddDevice<Keyboard>("V5ProbeKeyboard");var mouse=InputSystem.AddDevice<Mouse>("V5ProbeMouse");var lights=p.GetComponentsInChildren<Light2D>();var rows=new List<object>();var rt=RenderTexture.GetTemporary(320,180,24,RenderTextureFormat.ARGB32,RenderTextureReadWrite.sRGB);var tex=new Texture2D(320,180,TextureFormat.RGBA32,false);var previous=cam.targetTexture;var active=RenderTexture.active;string root="검증/플레이-사용성-v5/"+label;Directory.CreateDirectory(root);
 bool bg=Application.runInBackground;Application.runInBackground=true;InputSystem.EnableDevice(kb);InputSystem.EnableDevice(mouse);try{ScreenCapture.CaptureScreenshot(Path.GetFullPath(root+"/baseline-hud.png"));await Task.Delay(200);foreach(string phase in new[]{"idle","move","stop","near-wall","combat"}){if(phase=="near-wall"){p.Teleport(new Vector2(-5f,21.8f));follow.Snap();}if(phase=="combat"){var rat=Enemy.All.First(e=>e&&!e.Dead&&!e.IsDummy&&e.Kind==MonsterKind.Rat);p.Teleport(rat.Position+Vector2.left*2.8f);follow.Snap();}InputSystem.QueueStateEvent(kb,phase=="move"?new KeyboardState(Key.D):new KeyboardState());for(int i=0;i<32;i++){var aim=cam.WorldToScreenPoint(p.transform.position+Vector3.right*5);InputSystem.QueueStateEvent(mouse,new MouseState{position=aim});await Task.Delay(35);cam.targetTexture=rt;cam.Render();RenderTexture.active=rt;tex.ReadPixels(new Rect(0,0,320,180),0,0);tex.Apply();var samples=new List<float>();foreach(Vector2 delta in new[]{Vector2.left,Vector2.right,Vector2.up,Vector2.down}){var v=cam.WorldToViewportPoint((Vector2)p.transform.position+delta*.85f);Color c=tex.GetPixelBilinear(v.x,v.y);samples.Add(c.grayscale);}cam.targetTexture=previous;RenderTexture.active=active;var viewport=cam.WorldToViewportPoint(p.transform.position);rows.Add(new{phase,i,time=Time.unscaledTime,position=p.Position.ToString(),viewport=new[]{viewport.x,viewport.y},look=VisionSystem.Instance.LookDeg,nearVisible=VisionSystem.Instance.IsVisible(p.Position+Vector2.right*.85f),combat=DungeonLighting.Instance.InCombat,pose=p.Pose.ToString(),luminance=samples.ToArray(),lights=lights.Select(l=>new{l.name,l.enabled,active=l.gameObject.activeInHierarchy,l.intensity,inner=l.pointLightInnerRadius,outer=l.pointLightOuterRadius,angle=l.pointLightOuterAngle}).ToArray()});if(i==5||i==25)File.WriteAllBytes(root+"/probe-"+phase+"-"+i+".png",tex.EncodeToPNG());}}
 }finally{Application.runInBackground=bg;cam.targetTexture=previous;RenderTexture.active=active;RenderTexture.ReleaseTemporary(rt);UnityEngine.Object.DestroyImmediate(tex);InputSystem.RemoveDevice(kb);InputSystem.RemoveDevice(mouse);oldKb?.MakeCurrent();oldMouse?.MakeCurrent();p.Teleport(original);follow.Snap();}File.WriteAllText(root+"/light-probe.json",Newtonsoft.Json.JsonConvert.SerializeObject(rows,Newtonsoft.Json.Formatting.Indented));return new{samples=rows.Count,path=root+"/light-probe.json",method="Actual rendered floor probes and Light2D values; virtual movement input"};}}
